import 'vector_tile/vector_tile.dart';

void main() async {
  final data = await File('sample.pbf').readAsBytes();
  final tile = await VectorTile.fromBytes(bytes: data);
  final layer = tile.layers.first;
  for (var f in layer.features) {
    f.decodeGeometry();
    var geo = f.toGeoJson<GeoJsonPoint>(x: 0, y: 0, z: 0);
    print(geo?.geometry?.coordinates);
  }
}
